+*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#131d25;color:#f3f1e8;font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}.game{position:relative;width:100%;height:100%;overflow:hidden;background:#202c30}canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.topbar{position:absolute;top:0;left:0;right:0;height:68px;padding:13px 24px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,15,19,.83),transparent);pointer-events:none}.brand{font:900 23px 'Barlow Condensed',sans-serif;letter-spacing:2px}.brand span{color:#d5ed75}.district{font-size:10px;letter-spacing:2px;color:#cfdbd0;text-transform:uppercase;margin-top:2px}.cash{background:#101a20d9;border:1px solid #ffffff1c;border-radius:9px;padding:9px 14px;font-weight:800;font-size:14px}.cash b{color:#d5ed75}.panel{position:absolute;background:rgba(14,23,27,.93);border:1px solid rgba(255,255,255,.14);border-radius:12px;box-shadow:0 12px 36px #0005;backdrop-filter:blur(10px)}.character{top:79px;left:22px;width:230px;padding:15px}.eyebrow{font-size:9px;letter-spacing:1.7px;font-weight:800;color:#94a5a2;text-transform:uppercase}.playername{font:800 19px 'Barlow Condensed';letter-spacing:.5px;margin:4px 0 12px}.stats{display:grid;grid-template-columns:1fr 1fr;gap:8px 12px}.stat{font-size:10px;color:#b7c2be}.stat b{float:right;color:#eff3e6;font-size:11px}.bar{height:5px;background:#2b3839;border-radius:4px;margin-top:5px;overflow:hidden}.bar i{display:block;height:100%;background:#d5ed75;border-radius:4px;transition:width .3s}.bar.hp i{background:#e88168}.quest{top:79px;right:22px;width:260px;padding:15px}.questtitle{font:800 18px 'Barlow Condensed';margin:5px 0 6px}.quest p{font-size:11px;color:#bbc4bf;line-height:1.55;margin:0}.objective{margin-top:10px;padding-top:10px;border-top:1px solid #ffffff18;font-size:10px;color:#d5ed75;font-weight:700}.interact{position:absolute;left:50%;top:54%;transform:translate(-50%,-50%);display:none;padding:9px 15px;border-radius:7px;background:#0d171be8;border:1px solid #d5ed75;color:#f2f3e9;font-size:12px;font-weight:700;white-space:nowrap}.bottom{position:absolute;bottom:20px;left:22px;right:22px;display:flex;align-items:end;justify-content:space-between;pointer-events:none}.hint{font-size:10px;color:#c5ceca;background:#111a1de0;padding:9px 12px;border:1px solid #ffffff16;border-radius:8px}.hint strong{color:#d5ed75}.skills{display:flex;gap:6px;background:#111a1de8;padding:7px;border:1px solid #ffffff1c;border-radius:10px}.skill{height:31px;min-width:31px;border:1px solid #45524d;border-radius:6px;display:grid;place-items:center;font:700 11px 'Barlow Condensed';color:#d5ed75}.skill small{font:8px 'DM Sans';color:#a8b3ae;margin-left:3px}.toast{position:absolute;left:50%;top:22%;transform:translate(-50%,-8px);padding:10px 16px;border-radius:8px;background:#10191ee8;border:1px solid #d5ed75;color:#eef3df;font-size:12px;font-weight:700;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile{display:none}.minimap{position:absolute;right:22px;bottom:77px;width:116px;height:116px;border-radius:10px;border:2px solid #d3e57a;background:#17221edb;overflow:hidden}.minimap canvas{width:100%;height:100%}.mobilepad{position:absolute;left:20px;bottom:24px;display:none;grid-template-columns:repeat(3,48px);grid-template-rows:repeat(2,46px);gap:5px}.mobilepad button,.actionbtn{border:1px solid #ffffff30;border-radius:10px;background:#142022d9;font-size:18px;touch-action:none}.mobilepad button:nth-child(1){grid-column:2}.mobilepad button:nth-child(2){grid-column:1;grid-row:2}.mobilepad button:nth-child(3){grid-column:2;grid-row:2}.mobilepad button:nth-child(4){grid-column:3;grid-row:2}.actionbtn{display:none;position:absolute;right:24px;bottom:31px;width:60px;height:60px;border-color:#d5ed75;color:#d5ed75;font-weight:800;font-size:12px}.dialog{position:absolute;left:50%;bottom:95px;transform:translateX(-50%);width:min(420px,90vw);padding:17px 20px;display:none}.dialog h2{font:800 22px 'Barlow Condensed';margin:0 0 5px}.dialog p{font-size:12px;color:#c0cbc5;margin:0 0 12px}.dialog button{border:0;border-radius:6px;background:#d5ed75;color:#18221b;padding:9px 13px;font-size:11px;font-weight:800;cursor:pointer}.dialog .close{float:right;background:transparent;color:#aebbb3;padding:3px}
