+</style></head><body><main class="game"><canvas id="world"></canvas><div class="topbar"><div><div class="brand">VICE<span>BOUND</span></div><div class="district" id="district">VESPUCCI CANALS · LOS SANTOS</div></div><div class="cash">$ <b id="money">240</b></div></div><section class="panel character"><div class="eyebrow">Street profile · level <span id="level">1</span></div><div class="playername">THE NEW ARRIVAL</div><div class="stats"><div class="stat">HEALTH <b id="healthtxt">100 / 100</b><div class="bar hp"><i id="healthbar" style="width:100%"></i></div></div><div class="stat">STAMINA <b id="staminatxt">100%</b><div class="bar"><i id="staminabar" style="width:100%"></i></div></div><div class="stat">STREET XP <b id="xptxt">0 / 60</b><div class="bar"><i id="xpbar" style="width:0%"></i></div></div><div class="stat">REP <b id="reptxt">Rookie</b></div></div></section><section class="panel quest"><div class="eyebrow">Active job · <span id="queststep">01</span></div><div class="questtitle" id="questtitle">A Favor for Frankie</div><p id="questcopy">Frankie’s posted up by the boardwalk. Go say what’s up — every legend starts somewhere.</p><div class="objective" id="objective">◎ Find Frankie · Vespucci Beach</div></section><div class="interact" id="interact">E &nbsp; Talk to Frankie</div><div class="toast" id="toast"></div><div class="panel dialog" id="dialog"><button class="close" id="closeDialog">✕</button><div class="eyebrow">FRANKIE · LOCAL FIXER</div><h2 id="dialogtitle">You made it.</h2><p id="dialogcopy">Keep your head up out here. First, grab some work from the corner store.</p><button id="dialogbutton">I’m on it →</button></div><div class="bottom"><div class="hint"><strong>WASD</strong> move &nbsp;·&nbsp; <strong>E</strong> interact &nbsp;·&nbsp; <strong>SPACE</strong> sprint</div><div class="skills"><div class="skill">⚒<small id="craftlvl">1</small></div><div class="skill">✦<small id="scavlvl">1</small></div><div class="skill">◈<small id="combatlvl">1</small></div><div class="skill">⌖<small id="repmini">0</small></div></div></div><div class="minimap"><canvas id="map"></canvas></div><div class="mobilepad"><button data-dir="up">▲</button><button data-dir="left">◀</button><button data-dir="down">▼</button><button data-dir="right">▶</button></div><button class="actionbtn" id="mobileact">ACTION</button></main><script>
+(()=>{const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),map=document.getElementById('map'),mx=map.getContext('2d');let W,H,dpr=1;const world={w:2200,h:1800};const p={x:1090,y:900,health:100,stamina:100,money:240,xp:0,level:1,rep:0};let keys={},touch={},toastTimer,step=0,dialogOpen=false,cam={x:0,y:0};const roads=[{x:0,y:340,w:2200,h:130},{x:0,y:970,w:2200,h:140},{x:570,y:0,w:140,h:1800},{x:1450,y:0,w:140,h:1800}];const blocks=[{x:50,y:60,w:450,h:220,c:'#b79b70'},{x:760,y:70,w:590,h:210,c:'#a98264'},{x:1640,y:55,w:500,h:230,c:'#9b896f'},{x:60,y:540,w:430,h:350,c:'#bcaa7e'},{x:780,y:550,w:570,h:340,c:'#ad8968'},{x:1640,y:540,w:500,h:350,c:'#b8a274'},{x:55,y:1190,w:440,h:500,c:'#b39b70'},{x:780,y:1190,w:570,h:500,c:'#9f8264'},{x:1640,y:1190,w:500,h:500,c:'#bba67a'}];const water={x:1600,y:940,w:600,h:220};const npc=[{x:1070,y:430,type:'frankie',name:'Frankie',color:'#dca552'},{x:880,y:1050,type:'shop',name:'Corner Store',color:'#6dd1b0'},{x:1360,y:1040,type:'mechanic',name:'Mack',color:'#e67962'}];const items=[{x:900,y:470,type:'crate',label:'Supply crate',got:false},{x:420,y:1050,type:'scrap',label:'Scrap metal',got:false},{x:1760,y:770,type:'cash',label:'Loose cash',got:false},{x:1270,y:1100,type:'scrap',label:'Scrap metal',got:false},{x:400,y:1500,type:'crate',label:'Supply crate',got:false}];const rand=(a,b)=>a+Math.random()*(b-a);let buildings=[];blocks.forEach((b,bi)=>{const cols=Math.max(2,Math.floor(b.w/155)),rows=Math.max(1,Math.floor(b.h/145));for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){let x=b.x+c*b.w/cols+rand(7,19),y=b.y+r*b.h/rows+rand(8,17),w=b.w/cols-rand(24,45),h=b.h/rows-rand(28,44);buildings.push({x,y,w,h,c:b.c,shade:rand(-12,12),roof:Math.random()})}});const resize=()=>{dpr=Math.min(devicePixelRatio||1,2);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);map.width=map.clientWidth*dpr;map.height=map.clientHeight*dpr;mx.setTransform(dpr,0,0,dpr,0,0)};addEventListener('resize',resize);resize();const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);function roundRect(c,x,y,w,h,r,fill){c.fillStyle=fill;c.beginPath();c.roundRect(x,y,w,h,r);c.fill()}function draw(){ctx.clearRect(0,0,W,H);const scale=Math.max(W/1050,H/760);ctx.save();ctx.scale(scale,scale);const vw=W/scale,vh=H/scale;cam.x=Math.max(0,Math.min(world.w-vw,p.x-vw/2));cam.y=Math.max(0,Math.min(world.h-vh,p.y-vh/2));ctx.translate(-cam.x,-cam.y);ctx.fillStyle='#64734f';ctx.fillRect(0,0,world.w,world.h);
+// park & grass texture
+ctx.fillStyle='#74845a';ctx.fillRect(0,0,world.w,world.h);for(let i=0;i<340;i++){let x=(i*197)%world.w,y=(i*313)%world.h;ctx.fillStyle=i%2?'#819063':'#697d54';ctx.fillRect(x,y,rand(4,13),rand(3,8))}
+// water
+ctx.fillStyle='#568c8a';ctx.fillRect(water.x,water.y,water.w,water.h);ctx.fillStyle='#77aaa0';for(let i=0;i<28;i++){let x=water.x+(i*83)%water.w,y=water.y+(i*59)%water.h;ctx.fillRect(x,y,rand(20,60),2)}
+// roads
+roads.forEach((r,i)=>{ctx.fillStyle='#555b58';ctx.fillRect(r.x,r.y,r.w,r.h);ctx.fillStyle='#626764';if(r.w>r.h){ctx.fillRect(r.x,r.y+9,r.w,4);ctx.fillRect(r.x,r.y+r.h-13,r.w,4);ctx.setLineDash([20,24]);ctx.strokeStyle='#d5c98e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(r.x,r.y+r.h/2);ctx.lineTo(r.x+r.w,r.y+r.h/2);ctx.stroke();ctx.setLineDash([])}else{ctx.fillRect(r.x+9,r.y,4,r.h);ctx.fillRect(r.x+r.w-13,r.y,4,r.h);ctx.setLineDash([20,24]);ctx.strokeStyle='#d5c98e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(r.x+r.w/2,r.y);ctx.lineTo(r.x+r.w/2,r.y+r.h);ctx.stroke();ctx.setLineDash([])}});
+// sidewalks
+roads.forEach(r=>{ctx.fillStyle='#a99d80';ctx.fillRect(r.x,r.y,r.w<r.h?10:r.w,r.w<r.h?r.h:10);ctx.fillRect(r.x+(r.w<r.h?r.w-10:0),r.y+(r.w<r.h?0:r.h-10),r.w<r.h?10:r.w,r.w<r.h?r.h:10)});
+buildings.forEach((b,i)=>{ctx.fillStyle='#0003';ctx.fillRect(b.x+9,b.y+12,b.w,b.h);ctx.fillStyle=b.c;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle=`rgba(255,255,255,${.07+b.roof*.1})`;ctx.fillRect(b.x+5,b.y+5,b.w-10,8);ctx.fillStyle='#655d4c';ctx.fillRect(b.x+b.w*.12,b.y+b.h*.28,17,12);ctx.fillRect(b.x+b.w*.66,b.y+b.h*.28,17,12);ctx.fillStyle='#514f43';ctx.fillRect(b.x+b.w*.4,b.y+b.h-25,24,25);ctx.fillStyle='#7d8c73';ctx.fillRect(b.x+b.w*.2,b.y+b.h*.62,10,10);});
+// palms and streetlights
+for(let i=0;i<38;i++){let x=100+(i*293)%2000,y=490+(i*211)%1200;if(buildings.some(b=>x>b.x-22&&x<b.x+b.w+22&&y>b.y-22&&y<b.y+b.h+22))continue;ctx.fillStyle='#4e4735';ctx.fillRect(x-3,y-8,6,22);ctx.fillStyle='#33805d';for(let a=0;a<5;a++){ctx.beginPath();ctx.ellipse(x+Math.cos(a*1.26)*13,y-14+Math.sin(a*1.26)*7,12,5,a*1.26,0,Math.PI*2);ctx.fill()}}
+// cars
+for(let i=0;i<14;i++){let horizontal=i%2===0,x=horizontal?((i*239+190)%world.w):[640,1520][i%2],y=horizontal?[406,1035][i%2]:((i*171+80)%world.h);let colors=['#d1c27c','#b9513c','#567988','#dedbd0','#343b3d'];ctx.save();ctx.translate(x,y);if(!horizontal)ctx.rotate(Math.PI/2);roundRect(ctx,-22,-10,44,20,5,colors[i%colors.length]);ctx.fillStyle='#293d40';ctx.fillRect(-9,-7,19,14);ctx.fillStyle='#ddd2a1';ctx.fillRect(18,-7,3,4);ctx.restore()}
+// landmarks
+npc.forEach(n=>{ctx.fillStyle='#0004';ctx.beginPath();ctx.ellipse(n.x,n.y+9,14,6,0,0,7);ctx.fill();ctx.fillStyle=n.color;ctx.beginPath();ctx.arc(n.x,n.y,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#1d2929';ctx.fillRect(n.x-4,n.y+6,8,10);ctx.fillStyle='#fff';ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillText(n.name,n.x,n.y-18)});
+items.filter(it=>!it.got).forEach(it=>{ctx.fillStyle='#d7ec7c';ctx.beginPath();ctx.arc(it.x,it.y,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#192520';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.fillText(it.type==='cash'?'$':'+',it.x,it.y+5)});
+// player
+ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(p.x,p.y+13,13,6,0,0,7);ctx.fill();ctx.fillStyle='#e7d8b9';ctx.beginPath();ctx.arc(p.x,p.y-5,7,0,7);ctx.fill();ctx.fillStyle='#d5ed75';ctx.fillRect(p.x-8,p.y+1,16,15);ctx.fillStyle='#273b35';ctx.fillRect(p.x-8,p.y+14,6,8);ctx.fillRect(p.x+2,p.y+14,6,8);ctx.fillStyle='#212d2c';ctx.fillRect(p.x-7,p.y-8,14,4);ctx.restore();
+// map
+let mw=map.clientWidth,mh=map.clientHeight;mx.clearRect(0,0,mw,mh);mx.fillStyle='#71815b';mx.fillRect(0,0,mw,mh);mx.fillStyle='#535d5b';roads.forEach(r=>mx.fillRect(r.x/world.w*mw,r.y/world.h*mh,r.w/world.w*mw,r.h/world.h*mh));mx.fillStyle='#568c8a';mx.fillRect(water.x/world.w*mw,water.y/world.h*mh,water.w/world.w*mw,water.h/world.h*mh);buildings.forEach(b=>{mx.fillStyle='#b49c76';mx.fillRect(b.x/world.w*mw,b.y/world.h*mh,b.w/world.w*mw,b.h/world.h*mh)});npc.forEach(n=>{mx.fillStyle='#f0ae53';mx.fillRect(n.x/world.w*mw-2,n.y/world.h*mh-2,4,4)});mx.fillStyle='#d5ed75';mx.beginPath();mx.arc(p.x/world.w*mw,p.y/world.h*mh,3.3,0,7);mx.fill();requestAnimationFrame(draw)}
+function setToast(s){let t=document.getElementById('toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2200)}function updateUI(){document.getElementById('money').textContent=p.money;document.getElementById('level').textContent=p.level;document.getElementById('healthtxt').textContent=`${p.health} / 100`;document.getElementById('healthbar').style.width=p.health+'%';document.getElementById('staminatxt').textContent=Math.round(p.stamina)+'%';document.getElementById('staminabar').style.width=p.stamina+'%';let need=60+(p.level-1)*45;document.getElementById('xptxt').textContent=`${p.xp} / ${need}`;document.getElementById('xpbar').style.width=Math.min(100,p.xp/need*100)+'%';document.getElementById('reptxt').textContent=p.rep>5?'Local':p.rep>0?'Known face':'Rookie';document.getElementById('repmini').textContent=p.rep;document.getElementById('scavlvl').textContent=p.level;document.getElementById('craftlvl').textContent=p.level;document.getElementById('combatlvl').textContent=p.level}
+function earn(xp,money){p.xp+=xp;p.money+=money;p.rep++;let need=60+(p.level-1)*45;if(p.xp>=need){p.xp-=need;p.level++;p.health=100;setToast('LEVEL UP · You’re getting noticed.')}updateUI()}
